package app.kivo.store;
import android.os.Build;import android.util.JsonReader;import org.json.*;import java.io.*;import java.util.*;
/** IzzyOnDroid index verified using its published certificate, with separate persisted timestamp. */
final class Izzy {
 static final String BASE="https://apt.izzysoft.de/fdroid/repo", PIN="3bf0d6abfeae2f401707b6d966be743bf0eee49c2561b9ba39073711f628937a";
 final MainActivity host;volatile Map<String,JSONObject> entries=Collections.emptyMap();volatile boolean syncing;
 Izzy(MainActivity h){host=h;}
 void state(String st,String message){try{host.send("sourceState",new JSONObject().put("id","izzy").put("state",st).put("message",message).put("count",entries.size()).put("updated",host.prefs.getLong("izzyTimestamp",0)));}catch(Exception ignored){}}
 void apply(JSONArray data)throws Exception{Map<String,JSONObject> next=new HashMap<>();for(int i=0;i<data.length();i++){JSONObject a=data.getJSONObject(i);next.put(a.getString("repo"),a);}entries=Collections.unmodifiableMap(next);host.send("izzy",data);state("ready","");host.installedApps.requestScan();}
 void load(){try{File f=new File(host.getFilesDir(),"izzy-catalog.json");if(f.isFile())try(InputStream in=new FileInputStream(f)){apply(new JSONArray(MainActivity.read(in,24*1024*1024)));}else state("idle","");}catch(Exception e){state("error","No se pudo leer el catálogo guardado.");}}
 JSONObject find(String repo)throws Exception{JSONObject a=entries.get(MainActivity.repo(repo));if(a==null)throw new IOException("La app ya no está en el índice de IzzyOnDroid.");return a;}
 synchronized void sync(){if(syncing)return;syncing=true;host.prefs.edit().putLong("autoAttempt:izzy",System.currentTimeMillis()).apply();host.repoSync.execute(()->{File jar=null,index=null,temp=null;try{state("syncing","Descargando y verificando IzzyOnDroid…");jar=File.createTempFile("izzy-entry-",".jar",host.getCacheDir());fetch("/entry.jar",jar,1048576,null,-1);JSONObject entry=new JSONObject(new String(RepoTrust.entry(jar,PIN),"UTF-8"));long stamp=entry.getLong("timestamp");if(stamp<host.prefs.getLong("izzyTimestamp",0))throw new SecurityException("Índice anterior al guardado.");JSONObject ref=entry.getJSONObject("index");index=File.createTempFile("izzy-index-",".json",host.getCacheDir());fetch(ref.getString("name"),index,100*1024*1024,ref.getString("sha256"),ref.getLong("size"));JSONArray out=new JSONArray();try(JsonReader r=new JsonReader(new InputStreamReader(new FileInputStream(index),"UTF-8"))){r.beginObject();while(r.hasNext()){if(!r.nextName().equals("packages")){r.skipValue();continue;}r.beginObject();while(r.hasNext()){String pkg=r.nextName();JSONObject app=Fdroid.normalize(pkg,Fdroid.object(r),Build.VERSION.SDK_INT,Arrays.asList(Build.SUPPORTED_ABIS),"izzy",BASE);if(app!=null)out.put(app);}r.endObject();}r.endObject();}if(out.length()==0)throw new IOException("Índice sin aplicaciones compatibles.");temp=new File(host.getFilesDir(),"izzy-catalog.tmp");try(FileOutputStream stream=new FileOutputStream(temp)){stream.write(out.toString().getBytes("UTF-8"));stream.getFD().sync();}if(!temp.renameTo(new File(host.getFilesDir(),"izzy-catalog.json")))throw new IOException("No se pudo guardar el índice.");host.prefs.edit().putLong("izzyTimestamp",stamp).putLong("autoSuccess:izzy",System.currentTimeMillis()).apply();apply(out);host.status("IzzyOnDroid actualizado: "+out.length()+" aplicaciones.");}catch(Exception e){state("error","No se pudo cargar IzzyOnDroid: "+(e.getMessage()==null?"revisa la conexión.":e.getMessage())+(entries.isEmpty()?" Aún no hay catálogo guardado.":" Se conserva el catálogo disponible."));host.status("IzzyOnDroid: "+e.getMessage());}finally{if(jar!=null)jar.delete();if(index!=null)index.delete();if(temp!=null)temp.delete();syncing=false;}});}
 static void fetch(String path,File target,int max,String hash,long size)throws Exception{if(!Fdroid.safePath(path))throw new IOException("Ruta no válida.");java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL(BASE+path).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("Servidor respondió "+c.getResponseCode());java.security.MessageDigest md=java.security.MessageDigest.getInstance("SHA-256");long total=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(target)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){total+=n;if(total>max)throw new IOException("Índice demasiado grande.");out.write(b,0,n);md.update(b,0,n);}}if(size>=0&&total!=size)throw new IOException("Índice incompleto.");if(hash!=null&&(!hash.matches("[a-f0-9]{64}")||!RepoTrust.hex(md.digest()).equals(hash)))throw new SecurityException("La huella del índice no coincide.");}finally{c.disconnect();}}
}
